QUESTION_CORRECTIONS = {
    657: "Quyền yêu cầu thương lượng tập thể của các bên được quy định ra sao?",
    845: "Tai nạn lao động làm chết người hoặc làm bị thương nặng từ 02 người lao động trở lên phải được khai báo ngay với cơ quan nào?",
    849: "Thời hạn điều tra tai nạn lao động làm một người bị thương nặng là bao lâu và trường hợp nào được gia hạn?",
    847: "Tai nạn lao động làm chết người hoặc làm bị thương nặng từ 02 người lao động trở lên thuộc thẩm quyền điều tra của cấp nào?",
    855: "Khi xảy ra tai nạn lao động đặc biệt nghiêm trọng, người sử dụng lao động phải khai báo ngay bằng cách nào?",
    859: "Một tai nạn lao động làm một người bị thương nặng có thể được gia hạn điều tra trong trường hợp nào và gia hạn tối đa bao lâu?",
}

ANSWER_CORRECTIONS = {
    176: "Thương lượng tập thể là việc đàm phán, thỏa thuận giữa một bên là một hoặc nhiều tổ chức đại diện người lao động với một bên là một hoặc nhiều người sử dụng lao động hoặc tổ chức đại diện người sử dụng lao động nhằm xác lập điều kiện lao động, quy định về mối quan hệ giữa các bên và xây dựng quan hệ lao động tiến bộ, hài hòa và ổn định.",
    185: "Thỏa ước lao động tập thể vô hiệu từng phần khi một hoặc một số nội dung trong thỏa ước lao động tập thể vi phạm pháp luật.",
    311: "Có, nếu người lao động đang bị xử lý kỷ luật là thành viên của tổ chức đại diện người lao động tại cơ sở. Điểm b khoản 1 Điều 122 quy định khi đó việc xử lý kỷ luật phải có sự tham gia của tổ chức đại diện người lao động tại cơ sở mà người lao động là thành viên.",
    437: "Có. Người lao động thuộc các đối tượng được hưởng chế độ ốm đau theo khoản 1 Điều 42 Luật BHXH 2024, khi phải nghỉ việc để chăm sóc con dưới 07 tuổi bị ốm đau, thuộc trường hợp được hưởng chế độ ốm đau, trừ các trường hợp bị loại trừ tại khoản 2 Điều 42. Thời gian hưởng thực hiện theo Điều 44.",
    797: "Ít nhất 03 ngày làm việc trước ngày người lao động bắt đầu làm việc. Nghĩa vụ thông báo này chỉ áp dụng với trường hợp miễn giấy phép thuộc diện phải thông báo theo khoản 4 Điều 9 Nghị định 219/2025/NĐ-CP.",
    780: "Người sử dụng lao động phải khai báo ngay bằng phương thức nhanh nhất với Sở Nội vụ nơi xảy ra tai nạn và Công an cấp xã nơi xảy ra tai nạn. Nghĩa vụ này áp dụng khi tai nạn làm chết người hoặc làm bị thương nặng từ 02 người lao động trở lên.",
    781: "Thời hạn điều tra không quá 07 ngày kể từ khi nhận tin báo hoặc khai báo. Nếu tai nạn có tình tiết phức tạp, được gia hạn một lần nhưng không vượt quá thời hạn 07 ngày; Trưởng đoàn phải báo cáo và được người ra quyết định thành lập Đoàn đồng ý.",
    768: "Nếu quyền hoặc lợi ích của người lao động trong hợp đồng lao động đã ký thấp hơn thỏa ước lao động tập thể thì áp dụng quy định của thỏa ước. Nội quy, quy chế hoặc quy định khác của người sử dụng lao động chưa phù hợp phải được sửa đổi, bổ sung; trong thời gian chưa sửa đổi, áp dụng nội dung tương ứng của thỏa ước theo khoản 2 Điều 79 Bộ luật Lao động.",
    778: "Thông thường, Đoàn điều tra tai nạn lao động cấp tỉnh điều tra vụ tai nạn chết người hoặc làm từ 02 người lao động bị thương nặng trở lên. Ngoại lệ: vụ việc thuộc điểm c khoản 1 Điều 34 được điều tra theo pháp luật chuyên ngành; cơ quan trung ương có thể thành lập Đoàn điều tra hoặc điều tra lại khi tai nạn nghiêm trọng hay phức tạp vượt khả năng cấp tỉnh.",
    694: "Tranh chấp lao động cá nhân là tranh chấp giữa người lao động với người sử dụng lao động; giữa người lao động với doanh nghiệp, tổ chức đưa mình đi làm việc ở nước ngoài theo hợp đồng; hoặc giữa người lao động thuê lại với người sử dụng lao động thuê lại.",
    647: "Bên nhận yêu cầu thương lượng hợp lệ không được từ chối. Tổ chức đại diện người lao động chỉ có quyền yêu cầu khi đáp ứng ngưỡng thành viên và các điều kiện tại Điều 68; người sử dụng lao động cũng có thể yêu cầu thương lượng. Trong 07 ngày làm việc kể từ khi nhận yêu cầu và nội dung thương lượng, các bên phải thỏa thuận địa điểm, thời gian bắt đầu; ngày bắt đầu không được muộn hơn 30 ngày kể từ ngày nhận yêu cầu.",
    649: "Đối với thành viên ban lãnh đạo tổ chức đại diện người lao động, thời gian làm nhiệm vụ đại diện được hưởng chế độ thời giờ làm việc có trả lương trong giới hạn tối thiểu do Chính phủ quy định; thời gian tăng thêm do tổ chức và người sử dụng lao động thỏa thuận. Với đại diện tham gia đối thoại không thuộc ban lãnh đạo, quy chế dân chủ tại nơi làm việc phải quy định việc áp dụng Điều 176. Vì vậy không thể khẳng định mọi đại diện đều được nghỉ hưởng lương không giới hạn; cần xem quy chế và thỏa thuận áp dụng.",
    651: "Không thể ký thỏa ước nếu không đạt ngưỡng biểu quyết luật định. Thỏa ước cấp doanh nghiệp cần trên 50% toàn bộ người lao động trong doanh nghiệp tán thành; thỏa ước ngành cần trên 50% tổng số thành viên ban lãnh đạo được lấy ý kiến tán thành. Với thỏa ước nhiều doanh nghiệp, chỉ doanh nghiệp có trên 50% số người được lấy ý kiến tán thành mới tham gia ký. Sau khi được ký hợp lệ, thỏa ước có hiệu lực vào ngày các bên ghi trong thỏa ước; nếu không thỏa thuận ngày có hiệu lực thì có hiệu lực từ ngày ký.",
    636: "Người sử dụng lao động phải tổ chức đối thoại định kỳ ít nhất 01 lần trong năm. Đối thoại khi một bên yêu cầu hoặc khi có vụ việc luật định là các căn cứ bắt buộc riêng, không thay đổi tần suất tối thiểu này.",
    638: "Người sử dụng lao động phải tổ chức đối thoại khi có vụ việc thuộc điểm a khoản 1 Điều 36 (đơn phương chấm dứt HĐLĐ do người lao động thường xuyên không hoàn thành công việc); các trường hợp tại Điều 42, 44 về thay đổi cơ cấu, công nghệ hoặc lý do kinh tế và phương án sử dụng lao động; xây dựng thang lương, bảng lương, định mức lao động (Điều 93); quy chế thưởng (Điều 104); nội quy lao động (Điều 118); hoặc tạm đình chỉ công việc theo khoản 1 Điều 128 Bộ luật Lao động.",
    640: "Nội dung bắt buộc của cuộc đối thoại phụ thuộc vào vụ việc làm phát sinh nghĩa vụ đối thoại theo điểm c khoản 2 Điều 63: chấm dứt HĐLĐ theo điểm a khoản 1 Điều 36; thay đổi cơ cấu, công nghệ hoặc lý do kinh tế và phương án sử dụng lao động (Điều 42, 44); thang lương, bảng lương, định mức lao động (Điều 93); quy chế thưởng (Điều 104); nội quy lao động (Điều 118); hoặc tạm đình chỉ công việc (khoản 1 Điều 128). Danh sách chủ đề tại khoản 2 Điều 64 như tình hình sản xuất, kinh doanh, việc thực hiện hợp đồng và điều kiện làm việc là nội dung các bên lựa chọn, không phải tất cả đều bắt buộc trong mọi cuộc đối thoại.",
    642: "Đối thoại có đại diện của cả hai bên. Người sử dụng lao động quyết định số lượng, thành phần đại diện phía mình nhưng phải có ít nhất 03 người, trong đó có người đại diện theo pháp luật. Phía người lao động có tổ chức đại diện người lao động tại cơ sở; nếu có người lao động không phải thành viên tổ chức thì người sử dụng lao động phải phối hợp hướng dẫn, hỗ trợ và tạo điều kiện để họ tự lựa chọn nhóm đại diện đối thoại. Số lượng, thành phần phía người lao động được xác định theo Điều 38 Nghị định 145/2020/NĐ-CP.",
    644: "Người sử dụng lao động phải quy định trong quy chế dân chủ tại nơi làm việc các nội dung như nguyên tắc đối thoại; số lượng, thành phần đại diện; số lần, thời gian và cách thức tổ chức đối thoại; trách nhiệm các bên; và việc áp dụng Điều 176 Bộ luật Lao động. Đồng thời, khi xây dựng, sửa đổi hoặc bổ sung quy chế, phải tham khảo ý kiến tổ chức đại diện người lao động tại cơ sở và nhóm đại diện đối thoại (nếu có); không tham khảo ý kiến là hành vi bị xử phạt theo khoản 6 Điều 21 Nghị định 283/2026/NĐ-CP, có hiệu lực từ 10/09/2026.",
    832: "Người sử dụng lao động phải thường xuyên kiểm soát, quản lý yếu tố nguy hiểm theo yêu cầu kỹ thuật; đồng thời tổ chức kiểm tra, đánh giá yếu tố này ít nhất 01 lần mỗi năm để bảo đảm an toàn, vệ sinh lao động.",
    840: "Người sử dụng lao động phải thường xuyên kiểm soát, quản lý yếu tố nguy hiểm theo yêu cầu kỹ thuật; đồng thời tổ chức kiểm tra, đánh giá yếu tố này ít nhất 01 lần mỗi năm để bảo đảm an toàn, vệ sinh lao động.",
    852: "Nếu tai nạn không hoàn toàn do lỗi của người lao động, người sử dụng lao động phải bồi thường ít nhất 30 tháng tiền lương khi người lao động suy giảm khả năng lao động từ 81% trở lên; nếu người lao động chết do tai nạn lao động, thân nhân được bồi thường ít nhất 30 tháng tiền lương. Nếu tai nạn do lỗi của chính người lao động, khoản 5 Điều 38 quy định trợ cấp cho người lao động bị tai nạn ít nhất bằng 40% mức bồi thường tương ứng tại khoản 4. Vì vậy phải xác định lỗi; không áp dụng máy móc mức 30 tháng cho mọi trường hợp.",
    862: "Nếu tai nạn không hoàn toàn do lỗi của người lao động, người sử dụng lao động phải bồi thường ít nhất 30 tháng tiền lương khi người lao động suy giảm khả năng lao động từ 81% trở lên; nếu người lao động chết do tai nạn lao động, thân nhân được bồi thường ít nhất 30 tháng tiền lương. Nếu tai nạn do lỗi của chính người lao động, khoản 5 Điều 38 quy định trợ cấp cho người lao động bị tai nạn ít nhất bằng 40% mức bồi thường tương ứng tại khoản 4. Vì vậy phải xác định lỗi; không áp dụng máy móc mức 30 tháng cho mọi trường hợp.",
    42: "Ưu tiên nội dung của hợp đồng lao động. Khoản 2 Điều 22 quy định rằng nếu phụ lục chỉ nhằm quy định chi tiết nhưng dẫn đến cách hiểu khác với hợp đồng thì áp dụng nội dung hợp đồng lao động; nếu phụ lục sửa đổi, bổ sung thì phải ghi rõ điều khoản được sửa đổi và thời điểm có hiệu lực.",
    203: "Không. Từ ngày 10/09/2026, Nghị định 12/2022/NĐ-CP hết hiệu lực và Nghị định 283/2026/NĐ-CP có hiệu lực. Tuy nhiên phải xét quy định chuyển tiếp: (1) vi phạm đã xảy ra và kết thúc trước ngày này nhưng được phát hiện hoặc đang xem xét sau đó thì áp dụng quy định có hiệu lực tại thời điểm thực hiện hành vi; (2) vi phạm bắt đầu trước nhưng vẫn đang diễn ra khi Nghị định 283 có hiệu lực thì áp dụng Nghị định 283; (3) quyết định xử phạt đã ban hành hoặc thi hành xong trước ngày này nhưng còn khiếu nại thì áp dụng quy định có hiệu lực tại thời điểm ban hành quyết định. Vì vậy không thể chỉ căn cứ ngày mở hồ sơ.",
    204: "Có. Đối với đối thoại định kỳ, đối thoại theo yêu cầu và đối thoại trong các vụ việc phải đối thoại theo Điều 63 Bộ luật Lao động, diễn biến phải được ghi thành biên bản có chữ ký đúng thành phần tham gia. Chậm nhất 03 ngày làm việc sau khi kết thúc, người sử dụng lao động phải công bố công khai những nội dung chính tại nơi làm việc; tổ chức đại diện người lao động hoặc nhóm đại diện đối thoại phổ biến nội dung chính cho thành viên của mình. Riêng vụ việc tạm đình chỉ công việc theo khoản 1 Điều 128, các bên có thể trao đổi bằng văn bản hoặc trực tiếp theo khoản 2 Điều 41 Nghị định 145/2020/NĐ-CP.",
    216: "Không được tự ý khấu trừ lương để thu các khoản này. Theo khoản 1 Điều 102 Bộ luật Lao động, người sử dụng lao động chỉ được khấu trừ tiền lương để bồi thường thiệt hại do người lao động làm hư hỏng dụng cụ, thiết bị, tài sản của mình và người lao động có quyền biết lý do khấu trừ. Cần phân biệt: kinh phí công đoàn 2% quỹ tiền lương đóng BHXH là nghĩa vụ của người sử dụng lao động, không phải khoản trừ vào lương người lao động; đoàn phí là khoản do đoàn viên đóng theo Điều lệ Công đoàn. Đóng góp từ thiện là tự nguyện. Vì vậy, doanh nghiệp không được đơn phương trừ lương cho các khoản này khi người lao động chưa đồng ý.",
    219: "Trong thời gian tạm đình chỉ, người lao động được tạm ứng 50% tiền lương trước khi bị đình chỉ. Nếu cuối cùng không bị xử lý kỷ luật thì người sử dụng lao động phải trả đủ tiền lương cho thời gian đình chỉ; nếu bị xử lý kỷ luật thì người lao động không phải hoàn lại khoản tiền đã tạm ứng.",
    237: "Áp dụng mức lương tối thiểu cao nhất trong các địa bàn nơi khu công nghiệp đó nằm. Điểm c khoản 3 Điều 3 Nghị định 293/2025/NĐ-CP quy định người sử dụng lao động hoạt động trong khu công nghiệp, khu chế xuất, khu công nghệ cao hoặc khu công nghệ số tập trung nằm trên các địa bàn có mức lương tối thiểu khác nhau thì áp dụng theo địa bàn có mức cao nhất.",
    240: "Chưa thể kết luận vi phạm chỉ từ dữ kiện này. Điều 26 Bộ luật Lao động quy định lương thử việc do hai bên thỏa thuận nhưng ít nhất bằng 85% mức lương của công việc. Điều 90(2) Bộ luật và Nghị định 293/2025/NĐ-CP đặt mức sàn cho tiền lương theo công việc/chức danh của người lao động làm việc theo hợp đồng lao động; trong khi Điều 24 cho phép ghi nội dung thử việc trong hợp đồng lao động hoặc ký hợp đồng thử việc riêng. Pháp luật không nói rõ riêng rằng khoản lương thử việc bằng 85% trong tình huống này bắt buộc phải bằng 100% mức tối thiểu, nên không nên kết luận vi phạm chỉ vì con số thử việc thấp hơn mức tối thiểu. Cần xem hình thức và nội dung thỏa thuận; mức lương chính thức sau thử việc vẫn phải đáp ứng mức tối thiểu. Để chắc chắn tuân thủ, các bên có thể thỏa thuận lương thử việc không thấp hơn mức tối thiểu áp dụng.",
    247: "Không phải xin phép trước, nhưng phải thông báo bằng văn bản cho cơ quan chuyên môn về lao động cấp tỉnh. Theo khoản 1 Điều 62 Nghị định 145/2020/NĐ-CP, phải thông báo tại nơi tổ chức làm thêm và cả nơi đặt trụ sở chính nếu trụ sở ở tỉnh/thành khác.",
    248: "Phải gửi thông báo chậm nhất trong 15 ngày kể từ ngày thực hiện làm thêm từ trên 200 giờ đến 300 giờ trong năm. Đây là thời hạn thông báo, không phải thời hạn xin phép.",
    249: "Nếu thuộc đúng trường hợp làm công việc cần thiết để bảo vệ tính mạng, tài sản trong phòng ngừa hoặc khắc phục hậu quả thiên tai, hỏa hoạn, dịch bệnh nguy hiểm, thảm họa thì người lao động không được từ chối làm thêm. Ngoại lệ này không áp dụng nếu việc làm thêm có nguy cơ ảnh hưởng đến tính mạng, sức khỏe của chính người lao động theo pháp luật về an toàn, vệ sinh lao động.",
    276: "Được nghỉ ít nhất 30 phút liên tục. Nếu trong ngày làm việc có ít nhất 03 giờ làm việc trong khung giờ ban đêm thì thời gian nghỉ tối thiểu là 45 phút theo Điều 64 Nghị định 145/2020/NĐ-CP.",
    277: "Ít nhất 45 phút liên tục nếu người lao động làm việc từ 06 giờ trở lên trong ngày và có ít nhất 03 giờ làm việc trong khung giờ ban đêm (22 giờ đến 06 giờ). Trường hợp không đủ điều kiện này thì áp dụng mức nghỉ theo quy định chung.",
    308: "Người sử dụng lao động có từ 10 người lao động trở lên phải đăng ký nội quy tại cơ quan chuyên môn về lao động thuộc UBND cấp tỉnh nơi người sử dụng lao động đăng ký kinh doanh. Căn cứ khoản 1 Điều 119 Bộ luật Lao động.",
    329: "Người lao động phải bồi thường một phần hoặc toàn bộ thiệt hại theo thời giá thị trường hoặc nội quy lao động; nếu hai bên có hợp đồng trách nhiệm thì bồi thường theo hợp đồng đó. Căn cứ là khoản 2 Điều 129 Bộ luật Lao động.",
    338: "Lao động nữ đang nuôi con dưới 12 tháng tuổi được nghỉ 60 phút mỗi ngày trong giờ làm việc để cho con bú, vắt/trữ sữa hoặc nghỉ ngơi và vẫn hưởng đủ lương theo hợp đồng. Hai bên có thể thỏa thuận bố trí thời gian nghỉ linh hoạt. Nếu người lao động không có nhu cầu nghỉ và được người sử dụng lao động đồng ý tiếp tục làm việc, ngoài lương theo hợp đồng còn phải được trả thêm tiền lương theo công việc đã làm trong thời gian nghỉ. Không khẳng định thời gian làm việc thay cho giờ nghỉ này đương nhiên không tính là làm thêm giờ: khoản 4 Điều 80 Nghị định 145 chỉ nêu rõ việc trả thêm tiền lương, khác với quy định riêng về nghỉ trong thời gian hành kinh tại khoản 3 cùng điều.",
    342: "Có. Nếu cơ sở khám bệnh, chữa bệnh có thẩm quyền xác nhận tiếp tục làm việc sẽ ảnh hưởng xấu tới thai nhi, lao động nữ có quyền đơn phương chấm dứt hợp đồng hoặc tạm hoãn thực hiện hợp đồng. Nếu đơn phương chấm dứt theo trường hợp này thì không phải báo trước theo điểm đ khoản 2 Điều 35, nhưng phải thông báo cho người sử dụng lao động kèm xác nhận y tế theo khoản 1 Điều 138. Nếu chọn tạm hoãn, thời gian do hai bên thỏa thuận nhưng tối thiểu bằng thời gian cơ sở y tế chỉ định; nếu không có chỉ định về thời gian nghỉ thì hai bên thỏa thuận theo khoản 2 Điều 138.",
    344: "Khi sinh đôi trở lên, cứ mỗi con tính từ con thứ hai trở đi, người mẹ được nghỉ thêm 01 tháng theo khoản 1 Điều 139 Bộ luật Lao động. Cần tính cùng thời gian nghỉ cơ bản: 06 tháng thông thường, hoặc 07 tháng nếu đủ điều kiện hưởng chế độ sinh con thứ hai (theo Nghị định 168/2026/NĐ-CP, tại thời điểm sinh có một con đẻ còn sống). Vì vậy tổng thời gian phụ thuộc số con và điều kiện thực tế; không nên khẳng định mọi trường hợp sinh đôi đều nghỉ 08 tháng.",
    454: "Nếu thai từ đủ 22 tuần tuổi trở lên bị sảy thai và lao động nữ đủ điều kiện theo khoản 2, 3 hoặc 5 Điều 50 Luật BHXH, người mẹ và chồng được nghỉ hưởng thai sản theo Điều 53 như trường hợp sinh con (khoản 2 Điều 52). Tuy nhiên, Nghị định 168/2026/NĐ-CP loại trừ trường hợp tại khoản 2 Điều 52 khỏi chế độ nghỉ tăng thêm khi sinh con thứ hai; vì vậy không áp dụng riêng mức nghỉ 7 tháng/10 ngày của chính sách sinh con thứ hai cho trường hợp sảy thai này.",
    455: "Từ 01/07/2026, nếu vợ sinh một con bình thường thì lao động nam đang tham gia BHXH bắt buộc được nghỉ 05 ngày làm việc. Ngoại lệ quan trọng: nếu đây là lần sinh con thứ hai và tại thời điểm sinh người vợ có một con đẻ còn sống, người chồng đủ điều kiện hưởng BHXH thì được nghỉ 10 ngày làm việc. Trường hợp sinh con phải phẫu thuật hoặc con dưới 32 tuần tuổi: 07 ngày; sinh đôi: 10 ngày; sinh đôi phải phẫu thuật: 14 ngày. Khi sinh ba trở lên, được nghỉ thêm 03 ngày làm việc cho mỗi con từ con thứ ba. Thời gian nghỉ phải bắt đầu trong 60 ngày kể từ ngày sinh; nếu nghỉ nhiều đợt thì đợt cuối cũng phải bắt đầu trong 60 ngày đầu và tổng số ngày không vượt mức luật định. Nếu một ca đồng thời thuộc nhiều trường hợp nêu trên, cần xác nhận mức áp dụng với cơ quan BHXH thay vì tự cộng các mức.",
    457: "Nếu mẹ tham gia BHXH bắt buộc và qua đời sau khi sinh, cha hoặc người trực tiếp nuôi dưỡng được nghỉ để chăm con trong thời gian thai sản còn lại của mẹ. Nếu đây là lần sinh con thứ hai và tại thời điểm sinh người vợ có một con đẻ còn sống, thời gian thai sản của mẹ có thể là 07 tháng; người cha/người nuôi dưỡng nghỉ phần còn lại theo quy định. Nếu mẹ tham gia BHXH nhưng không đủ điều kiện thai sản theo khoản 2, 3 hoặc 5 Điều 50 mà qua đời, cha/người trực tiếp nuôi dưỡng được nghỉ đến khi con đủ 06 tháng tuổi. Trường hợp chỉ có cha tham gia BHXH và mẹ chết hoặc không đủ sức khỏe chăm con sau sinh thì áp dụng khoản 7 Điều 53, thời gian nghỉ đến khi con đủ 06 tháng tuổi.",
    363: "Không được, trừ khi chính người lao động đồng ý. Khoản 1 Điều 160 cấm bố trí làm thêm giờ hoặc làm việc ban đêm đối với người khuyết tật nhẹ có mức suy giảm khả năng lao động từ 51% trở lên, người khuyết tật nặng hoặc đặc biệt nặng, trừ trường hợp người lao động đồng ý. Vì vậy nhóm được hỏi chỉ có thể làm thêm/ban đêm khi họ đồng ý.",
    367: "Về nguyên tắc, không được để người lao động bắt đầu làm rồi mới giao kết HĐLĐ: hợp đồng phải được giao kết trước khi nhận người lao động vào làm việc. Tuy nhiên, nếu công việc có thời hạn dưới 01 tháng và không thuộc trường hợp pháp luật bắt buộc phải lập văn bản, hai bên có thể giao kết bằng lời nói; khi đó, thỏa thuận miệng phải được xác lập trước ngày làm đầu tiên, còn việc ký giấy cuối tuần chỉ có thể là ghi nhận lại thỏa thuận đã có. Nếu chưa hề giao kết trước khi làm hoặc thuộc trường hợp bắt buộc lập văn bản thì ký sau là không đúng thời điểm luật yêu cầu.",
    369: "Có. Theo khoản 2 Điều 16, người lao động phải cung cấp trung thực cho người sử dụng lao động họ tên, ngày tháng năm sinh, giới tính, nơi cư trú, trình độ học vấn, trình độ kỹ năng nghề, xác nhận tình trạng sức khỏe và thông tin khác liên quan trực tiếp đến việc giao kết mà người sử dụng lao động yêu cầu. Khoản này không liệt kê giấy tờ tùy thân như một thông tin bắt buộc phải cung cấp theo Điều 16.",
    380: "Nếu thử việc không đạt yêu cầu thì chấm dứt HĐLĐ đã giao kết nếu thử việc được ghi trong HĐLĐ, hoặc chấm dứt hợp đồng thử việc riêng; người sử dụng lao động phải thông báo kết quả thử việc khi kết thúc thời gian thử việc. Trong thời gian thử việc, mỗi bên cũng có quyền hủy hợp đồng thử việc hoặc HĐLĐ đã giao kết mà không cần báo trước và không phải bồi thường.",
    162: "Thông thường, hai bên phải thanh toán đầy đủ các khoản liên quan trong 14 ngày làm việc kể từ ngày HĐLĐ chấm dứt. Chỉ được kéo dài, tối đa 30 ngày, nếu thuộc một trong các trường hợp tại khoản 1 Điều 48: người sử dụng lao động không phải là cá nhân chấm dứt hoạt động; người sử dụng lao động thay đổi cơ cấu, công nghệ hoặc vì lý do kinh tế; chia, tách, hợp nhất, sáp nhập, bán, cho thuê, chuyển đổi loại hình doanh nghiệp hoặc chuyển nhượng quyền sở hữu, quyền sử dụng tài sản của doanh nghiệp, hợp tác xã; hoặc do thiên tai, hỏa hoạn, địch họa, dịch bệnh nguy hiểm.",
    168: "Người sử dụng lao động phải bố trí nơi làm việc, cung cấp thông tin và bảo đảm các điều kiện cần thiết cho hoạt động của ban lãnh đạo tổ chức đại diện người lao động tại cơ sở. Bộ luật không ấn định danh mục phương tiện cụ thể tại Điều 178; điều kiện và phương tiện hoạt động có thể được các bên đưa ra thương lượng tập thể theo khoản 5 Điều 67.",
    258: "Có, nhưng chỉ với nghề, công việc thuộc danh mục tại Phụ lục V Thông tư 09/2020/TT-BLĐTBXH; thời giờ làm việc vẫn không quá 08 giờ trong một ngày và 40 giờ trong một tuần. Đây không phải quyền bố trí làm thêm đối với mọi công việc của người từ đủ 15 đến chưa đủ 18 tuổi.",
    528: "Năm 2026, tuổi nghỉ hưu trong điều kiện bình thường của lao động nam là 61 tuổi 6 tháng. Theo Điều 5 Nghị định 135/2020/NĐ-CP, nhóm được nghỉ sớm tối đa 05 năm (các khoản 1–4) có thể nghỉ từ 56 tuổi 6 tháng nếu đủ điều kiện. Riêng người có từ đủ 15 năm khai thác than trong hầm lò (khoản 5) hoặc bị suy giảm khả năng lao động từ 81% trở lên (khoản 6) có thể nghỉ sớm tối đa 10 năm, tức từ 51 tuổi 6 tháng. Vì câu hỏi không nêu rõ thuộc nhóm nào, không thể khẳng định chung mốc 56 tuổi 6 tháng là tuổi thấp nhất của tất cả trường hợp.",
    531: "Có, nhưng phải được người sử dụng lao động đồng ý theo thỏa thuận để tiếp tục làm việc sau tuổi nghỉ hưu bình thường. Thời gian kéo dài này không quá 05 năm, trừ trường hợp pháp luật có quy định khác (khoản 1 và khoản 2 Điều 6 Nghị định 135/2020/NĐ-CP).",
    568: "Không. Lương phải được trả bằng tiền mặt hoặc chuyển vào tài khoản cá nhân của người lao động, không được trả thay bằng sản phẩm/hiện vật. Người sử dụng lao động cũng không được ép người lao động dùng lương để mua hàng hóa hoặc dịch vụ do mình hay đơn vị khác chỉ định.",
    578: "Khi tổ chức làm thêm từ trên 200 giờ đến 300 giờ trong một năm, người sử dụng lao động phải gửi thông báo chậm nhất 15 ngày kể từ ngày bắt đầu thực hiện việc làm thêm đó (khoản 2 Điều 62 Nghị định 145/2020/NĐ-CP).",
    587: "Có. Thời gian khám sức khỏe, khám phát hiện bệnh nghề nghiệp do người sử dụng lao động bố trí hoặc yêu cầu được tính là thời giờ làm việc có hưởng nguyên lương theo khoản 9 Điều 58 Nghị định 145/2020/NĐ-CP.",
    605: "Người từ đủ 15 đến chưa đủ 18 tuổi tuyệt đối không được bố trí làm việc tại sòng bạc, quán bar, vũ trường, phòng hát karaoke, khách sạn, nhà nghỉ, cơ sở tắm hơi, xoa bóp, điểm kinh doanh xổ số hoặc dịch vụ trò chơi điện tử (điểm d khoản 2 Điều 147 Bộ luật Lao động). Người từ đủ 13 đến chưa đủ 15 tuổi cũng không được làm việc tại các địa điểm này: ngoài việc chỉ được làm công việc nhẹ trong danh mục, nơi làm việc không được thuộc các điểm a–d khoản 2 Điều 147 (điểm b khoản 5 Điều 3 Thông tư 09/2020/TT-BLĐTBXH). Người chưa đủ 13 tuổi về nguyên tắc không được tuyển dụng; ngoại lệ chỉ áp dụng cho công việc nghệ thuật, thể dục, thể thao không gây hại và phải được cơ quan chuyên môn về lao động cấp tỉnh đồng ý. Vì vậy, chỉ khi biết chính xác tuổi và công việc mới đánh giá được ngoại lệ rất hẹp này; không thể coi đây là quyền bố trí lao động thông thường tại các cơ sở nói trên.",
    607: "Người nước ngoài kết hôn với công dân Việt Nam và sinh sống trên lãnh thổ Việt Nam không thuộc diện cấp giấy phép lao động theo khoản 8 Điều 154 Bộ luật Lao động. Tuy nhiên, khoản 4 Điều 9 Nghị định 219/2025/NĐ-CP vẫn yêu cầu người sử dụng lao động thông báo trước ít nhất 03 ngày làm việc cho cơ quan có thẩm quyền cấp giấy xác nhận không thuộc diện cấp giấy phép tại nơi người đó dự kiến làm việc; không phải xin giấy xác nhận. Theo Điều 4, UBND cấp tỉnh có thẩm quyền và có thể phân cấp việc này cho cơ quan khác, nên cơ quan tiếp nhận cụ thể tùy quyết định phân cấp hiện hành của địa phương.",
    629: "Cần phân biệt nơi chưa có Công đoàn cơ sở với nơi chưa có bất kỳ tổ chức đại diện người lao động tại cơ sở nào. Theo khoản 1 Điều 20 Luật Công đoàn, ở nơi chưa có tổ chức đại diện người lao động tại cơ sở, Công đoàn có quyền và trách nhiệm đại diện, bảo vệ quyền và lợi ích hợp pháp, chính đáng của người lao động khi họ yêu cầu hoặc khi Công đoàn phát hiện dấu hiệu người sử dụng lao động xâm phạm quyền, lợi ích đó. Việc tổ chức đối thoại và thương lượng tập thể vẫn theo pháp luật lao động. Riêng khoản 2 Điều 19 cho phép Công đoàn cấp trên cơ sở cử cán bộ đến doanh nghiệp để tuyên truyền, vận động, hướng dẫn người lao động gia nhập hoặc thành lập Công đoàn cơ sở. Do đó không nên khẳng định quyền đại diện này chỉ dành riêng cho Công đoàn cấp trên trực tiếp cơ sở trong mọi doanh nghiệp không có Công đoàn cơ sở.",
    630: "Tổ chức đại diện người lao động có thể yêu cầu đối thoại tại nơi làm việc theo các trường hợp luật định, gồm đối thoại định kỳ ít nhất mỗi năm một lần, khi một hoặc các bên yêu cầu và một số vụ việc bắt buộc (khoản 2 Điều 63). Quyền yêu cầu thương lượng tập thể không tự động thuộc mọi tổ chức: tổ chức phải đạt tỷ lệ thành viên tối thiểu do Chính phủ quy định; nếu có nhiều tổ chức đủ điều kiện thì tổ chức có số thành viên lớn nhất được yêu cầu thương lượng, còn các tổ chức có thể tự nguyện kết hợp nếu không tổ chức nào riêng lẻ đạt ngưỡng (Điều 68).",
    633: "Không phải mọi tổ chức đại diện người lao động đều mặc nhiên có quyền đình công. Theo Điều 198–199 Bộ luật Lao động, chỉ tổ chức có quyền thương lượng tập thể và là một bên của tranh chấp lao động tập thể về lợi ích mới được tổ chức, lãnh đạo đình công; quyền này phát sinh trong các trường hợp luật định sau hòa giải không thành/hết hạn hòa giải hoặc khi thủ tục trọng tài không giải quyết được theo luật. Trước khi đình công, tổ chức phải thực hiện thủ tục lấy ý kiến, ra quyết định và thông báo theo các Điều 200–202.",
    354: "Có thể, nhưng chỉ trong các nghề, công việc thuộc danh mục được phép theo quy định; thời giờ làm việc vẫn không quá 08 giờ/ngày và 40 giờ/tuần. Vì vậy không được bố trí làm thêm giờ hoặc làm ban đêm cho mọi công việc của người từ đủ 15 đến chưa đủ 18 tuổi.",
    356: "Không được bố trí người từ đủ 15 đến chưa đủ 18 tuổi làm việc tại các địa điểm luật liệt kê như sòng bạc, quán bar, vũ trường, karaoke, khách sạn, nhà nghỉ, cơ sở tắm hơi hoặc xoa bóp, điểm kinh doanh xổ số và dịch vụ trò chơi điện tử. Người từ đủ 13 đến chưa đủ 15 tuổi chỉ được làm công việc nhẹ trong danh mục cho phép và phải đáp ứng điều kiện về nơi làm việc; không thể suy ra rằng mọi công việc hoặc địa điểm khác đều được phép.",
    376: "Ưu tiên nội dung của hợp đồng lao động. Khoản 2 Điều 22 quy định rằng nếu phụ lục chỉ nhằm quy định chi tiết nhưng dẫn đến cách hiểu khác với hợp đồng thì áp dụng nội dung hợp đồng lao động; nếu phụ lục sửa đổi, bổ sung thì phải ghi rõ điều khoản được sửa đổi và thời điểm có hiệu lực.",
    482: "Nếu người lao động đã đủ điều kiện hưởng lương hưu nhưng tiếp tục đóng bảo hiểm xã hội, phần thời gian đóng thêm kể từ sau khi đủ tuổi nghỉ hưu đến khi nghỉ hưu thực tế được tính trợ cấp một lần bằng 02 lần mức bình quân tiền lương làm căn cứ đóng BHXH cho mỗi năm đóng cao hơn số năm quy định. Căn cứ là khoản 2 Điều 68 Luật Bảo hiểm xã hội 2024.",
    500: "Có thể hưởng, nhưng không phải chỉ cần không tiếp tục cư trú tại Việt Nam là được nhận ngay. Người lao động nước ngoài phải thuộc đối tượng tại khoản 2 Điều 2, đã chấm dứt tham gia BHXH và có đề nghị hưởng; khi đó, điểm d khoản 2 Điều 70 cho phép hưởng BHXH một lần nếu người lao động đủ điều kiện hưởng lương hưu nhưng không tiếp tục cư trú tại Việt Nam. Nếu vẫn đang làm việc và tham gia BHXH thì riêng việc dự định rời Việt Nam chưa đủ điều kiện giải quyết.",
    506: "Thân nhân có thể hưởng gồm: (1) các con; trong đó, con được sinh ra sau khi người cha chết khi người mẹ đang mang thai, hoặc khi người mang thai hộ đang mang thai mà người cha hoặc người mẹ nhờ mang thai hộ chết, được hưởng đến khi đủ 18 tuổi; con suy giảm khả năng lao động từ 81% trở lên cũng thuộc diện luật định; (2) vợ hoặc chồng đủ tuổi theo khoản 2 Điều 169 Bộ luật Lao động, hoặc chưa đủ tuổi nhưng suy giảm khả năng lao động từ 81% trở lên; (3) cha, mẹ đẻ, cha mẹ đẻ của vợ/chồng và thành viên khác trong gia đình mà người chết có nghĩa vụ nuôi dưỡng, nếu đáp ứng điều kiện tuổi hoặc mức suy giảm khả năng lao động tương ứng. Đây là các nhóm thân nhân tại khoản 2 Điều 86; quyền hưởng còn phụ thuộc điều kiện của người chết và các quy định liên quan tại Điều này.",
    509: "Thời điểm hưởng trợ cấp tuất hằng tháng được tính từ ngày đầu tiên của tháng liền kề sau tháng người tham gia BHXH chết hoặc bị Tòa án tuyên bố là đã chết. Riêng con được sinh sau khi người cha chết, hoặc sau khi người cha là chồng của người mẹ nhờ mang thai hộ hay người mẹ nhờ mang thai hộ chết trong thời gian mang thai hộ, thì thời điểm hưởng của con được tính từ tháng con được sinh (khoản 3 Điều 87).",
    480: "Quy tắc chung tại khoản 3 Điều 66: sau khi tính tỷ lệ lương hưu, mỗi năm nghỉ hưu trước tuổi bị giảm 2%; nghỉ trước dưới 06 tháng không giảm, từ đủ 06 đến dưới 12 tháng giảm 1%. Ngoại lệ hiện hành: người thuộc khoản 2 Điều 26 Luật Nhà giáo được tính lương hưu theo khoản 3a Điều 66, không bị giảm tỷ lệ do nghỉ ở tuổi thấp hơn. Vì vậy cần xác định người lao động có thuộc đúng nhóm nhà giáo này không trước khi áp dụng mức giảm.",
    606: "Hai bên có thể thỏa thuận chi phí ăn, ở hằng tháng của người giúp việc gia đình, nhưng đây không phải khoản người sử dụng lao động được tự ý khấu trừ. Theo khoản 2 Điều 89 Nghị định 145/2020/NĐ-CP, mức chi phí ăn, ở tối đa không quá 50% mức lương theo công việc ghi trong hợp đồng lao động.",
    581: "Không. Giờ làm thêm không được cộng dồn để tạo thêm ngày nghỉ hằng năm. Tuy nhiên, thời gian dùng để tính ngày nghỉ phép không chỉ gồm thời gian làm việc bình thường: Điều 65 Nghị định 145/2020/NĐ-CP còn liệt kê một số khoảng nghỉ hoặc thời gian được tính như thời gian làm việc, như nghỉ có hưởng lương, nghỉ thai sản và một số thời gian nghỉ ốm trong giới hạn luật định. Các khoảng đó được tính theo Điều 65; bản thân giờ làm thêm không được liệt kê là thời gian cộng thêm để tăng phép năm.",
    977: "Có, nếu người lao động thuộc nhóm được áp dụng chế độ ốm đau theo khoản 1 Điều 42, phải nghỉ để trực tiếp chăm sóc con dưới 07 tuổi bị ốm và không thuộc trường hợp loại trừ tại khoản 2 Điều 42. Đây là trường hợp được nêu tại điểm e khoản 1 Điều 42. Thời gian hưởng trong năm tính theo ngày làm việc và tối đa là 20 ngày cho mỗi con dưới 03 tuổi hoặc 15 ngày cho mỗi con từ đủ 03 đến dưới 07 tuổi; nếu cả cha và mẹ cùng tham gia BHXH bắt buộc thì hạn mức áp dụng riêng cho mỗi người (Điều 44).",
    917: "Nếu người lao động nước ngoài làm việc cho cùng một người sử dụng lao động tại nhiều tỉnh/thành phố, UBND cấp tỉnh nơi người sử dụng lao động đặt trụ sở chính có thẩm quyền cấp giấy phép lao động hoặc giấy xác nhận không thuộc diện cấp giấy phép lao động; UBND tỉnh có thể phân cấp cơ quan thực hiện. Vì vậy cần nộp hồ sơ theo kênh tiếp nhận của địa phương có thẩm quyền, không chọn tùy ý một tỉnh nơi làm việc. Căn cứ trực tiếp là khoản 1 Điều 4 Nghị định 219/2025/NĐ-CP.",
    935: "Nếu người lao động nước ngoài làm việc cho cùng một người sử dụng lao động tại nhiều tỉnh/thành phố, UBND cấp tỉnh nơi người sử dụng lao động đặt trụ sở chính có thẩm quyền cấp giấy phép lao động hoặc giấy xác nhận không thuộc diện cấp giấy phép lao động; UBND tỉnh có thể phân cấp cơ quan thực hiện. Vì vậy cần nộp hồ sơ theo kênh tiếp nhận của địa phương có thẩm quyền, không chọn tùy ý một tỉnh nơi làm việc. Căn cứ trực tiếp là khoản 1 Điều 4 Nghị định 219/2025/NĐ-CP.",
    791: "Cơ sở sản xuất, kinh doanh phải thanh toán chi phí kiểm định kỹ thuật an toàn lao động; khoản chi này được hạch toán vào chi phí sản xuất, kinh doanh. Căn cứ trực tiếp là khoản 5 Điều 45 Nghị định 44/2016/NĐ-CP.",
    804: "Có 3 nhóm hình thức: (1) Hợp đồng đưa người lao động đi làm việc ở nước ngoài ký với đơn vị sự nghiệp để thực hiện thỏa thuận quốc tế; (2) hợp đồng hoặc thỏa thuận bằng văn bản với doanh nghiệp Việt Nam hoạt động dịch vụ, doanh nghiệp Việt Nam trúng thầu/nhận thầu ở nước ngoài, doanh nghiệp đưa người lao động đi đào tạo nâng cao kỹ năng nghề, hoặc tổ chức/cá nhân Việt Nam đầu tư ra nước ngoài; (3) hợp đồng lao động do người lao động trực tiếp ký với người sử dụng lao động ở nước ngoài.",
    808: "Có. Ký quỹ là điều kiện để được cấp Giấy phép hoạt động dịch vụ. Tiền ký quỹ gửi tại ngân hàng và chỉ được sử dụng theo yêu cầu của cơ quan nhà nước có thẩm quyền khi doanh nghiệp không thực hiện hoặc thực hiện không đầy đủ nghĩa vụ với người lao động. Trong 30 ngày kể từ ngày tiền ký quỹ được sử dụng, doanh nghiệp phải hoàn trả số tiền đã sử dụng và bảo đảm mức ký quỹ theo quy định.",
    773: "Có. Khi xây dựng kế hoạch, nội quy, quy trình hoặc biện pháp bảo đảm an toàn, vệ sinh lao động, người sử dụng lao động phải lấy ý kiến Ban chấp hành công đoàn cơ sở. Căn cứ điểm g khoản 2 Điều 7; luật quy định cụ thể chủ thể được lấy ý kiến là Ban chấp hành công đoàn cơ sở.",
    827: "Có. Khi xây dựng kế hoạch, nội quy, quy trình hoặc biện pháp bảo đảm an toàn, vệ sinh lao động, người sử dụng lao động phải lấy ý kiến Ban chấp hành công đoàn cơ sở. Căn cứ điểm g khoản 2 Điều 7; luật quy định cụ thể chủ thể được lấy ý kiến là Ban chấp hành công đoàn cơ sở.",
    828: "Không. Che giấu tai nạn lao động, bệnh nghề nghiệp hoặc khai báo, báo cáo sai sự thật về các sự việc này là hành vi bị nghiêm cấm theo khoản 1 Điều 12 Luật An toàn, vệ sinh lao động.",
    837: "Không. Trả tiền thay cho việc bồi dưỡng bằng hiện vật bị nghiêm cấm theo khoản 7 Điều 12. Việc bồi dưỡng được thực hiện trong ca hoặc ngày làm việc, trừ trường hợp đặc biệt do tổ chức lao động không thể bố trí bồi dưỡng tập trung tại chỗ (điểm c khoản 2 Điều 24).",
    845: "Phải khai báo ngay bằng cách nhanh nhất với Sở Nội vụ nơi xảy ra tai nạn và Công an cấp xã nơi xảy ra tai nạn. Áp dụng khi tai nạn chết người hoặc làm bị thương nặng từ 02 người lao động trở lên; Nghị định 129/2025/NĐ-CP quy định đầu mối tiếp nhận hiện hành.",
    846: "Người sử dụng lao động thành lập Đoàn điều tra tai nạn lao động cấp cơ sở để điều tra tai nạn làm người lao động bị thương nhẹ hoặc làm một người bị thương nặng thuộc quyền quản lý của mình, trừ trường hợp thuộc thẩm quyền điều tra cấp tỉnh, cấp trung ương hoặc theo pháp luật chuyên ngành. Riêng tai nạn làm một người làm việc không theo hợp đồng lao động bị thương nặng, Ủy ban nhân dân cấp xã nơi xảy ra tai nạn lập biên bản ghi nhận sự việc để thống kê tai nạn lao động theo khoản 1 Điều 43 Nghị định 129/2025/NĐ-CP.",
    847: "Theo khoản 2 Điều 35 Luật An toàn, vệ sinh lao động, vụ tai nạn lao động chết người hoặc làm bị thương nặng từ 02 người lao động trở lên thông thường do Đoàn điều tra tai nạn lao động cấp tỉnh điều tra. Theo khoản 3, cơ quan trung ương có thẩm quyền có thể thành lập Đoàn điều tra cấp trung ương khi xét thấy tai nạn nghiêm trọng hoặc việc điều tra phức tạp vượt khả năng của Đoàn cấp tỉnh; Đoàn cấp trung ương cũng có thể điều tra lại vụ việc do cấp tỉnh đã điều tra. Riêng các vụ thuộc điểm c khoản 1 Điều 34 (lĩnh vực phóng xạ, dầu khí, giao thông vận tải và đơn vị thuộc lực lượng vũ trang), việc điều tra thực hiện theo pháp luật chuyên ngành, có sự phối hợp của Thanh tra an toàn, vệ sinh lao động theo khoản 4 Điều 35.",
    848: "Không quá 04 ngày; thời hạn được tính từ khi nhận tin báo hoặc khai báo tai nạn đến khi công bố biên bản điều tra tai nạn lao động.",
    849: "Thời hạn điều tra không quá 07 ngày, tính từ khi nhận tin báo/khai báo đến khi công bố biên bản. Nếu vụ tai nạn có tình tiết phức tạp, được gia hạn một lần nhưng thời gian gia hạn không vượt quá thời hạn 07 ngày này; Trưởng đoàn phải báo cáo và được người ra quyết định thành lập Đoàn đồng ý. Căn cứ điểm b và đoạn cuối điểm d khoản 6 Điều 35 Luật An toàn, vệ sinh lao động.",
    855: "Phải khai báo ngay bằng phương thức nhanh nhất với Sở Nội vụ nơi xảy ra tai nạn và Công an cấp xã nơi xảy ra tai nạn. Nghĩa vụ này áp dụng khi tai nạn làm chết người hoặc làm bị thương nặng từ 02 người lao động trở lên; Nghị định 129/2025/NĐ-CP quy định đầu mối tiếp nhận hiện hành.",
    858: "Không quá 04 ngày; thời hạn được tính từ khi nhận tin báo hoặc khai báo tai nạn đến khi công bố biên bản điều tra tai nạn lao động.",
    859: "Đối với tai nạn làm một người bị thương nặng, thời hạn điều tra ban đầu không quá 07 ngày. Nếu có tình tiết phức tạp, được gia hạn một lần nhưng thời gian gia hạn không vượt quá thời hạn 07 ngày; Trưởng đoàn phải báo cáo và được người ra quyết định thành lập Đoàn đồng ý. Căn cứ điểm b và đoạn cuối điểm d khoản 6 Điều 35 Luật An toàn, vệ sinh lao động.",
    867: "Để hưởng chế độ bệnh nghề nghiệp, người lao động phải mắc bệnh thuộc Danh mục do Bộ trưởng Bộ Y tế ban hành và bị suy giảm khả năng lao động từ 5% trở lên do bệnh đó.",
    868: "Có thể. Người đã nghỉ hưu hoặc không còn làm các nghề, công việc có nguy cơ thuộc Danh mục bệnh nghề nghiệp, nếu phát hiện mắc bệnh trong thời gian quy định thì được giám định để xem xét giải quyết chế độ. Ngoài điều kiện này, vẫn phải đáp ứng khoản 1 Điều 46: bệnh thuộc Danh mục và suy giảm khả năng lao động từ 5% trở lên do bệnh đó.",
    869: "Được hưởng trợ cấp một lần nếu mức suy giảm khả năng lao động từ 5% đến 30%.",
    870: "Được hưởng trợ cấp hằng tháng nếu mức suy giảm khả năng lao động từ 31% trở lên.",
    875: "Để hưởng chế độ bệnh nghề nghiệp, người lao động phải mắc bệnh thuộc Danh mục do Bộ trưởng Bộ Y tế ban hành và bị suy giảm khả năng lao động từ 5% trở lên do bệnh đó.",
    876: "Có thể. Người đã nghỉ hưu hoặc không còn làm các nghề, công việc có nguy cơ thuộc Danh mục bệnh nghề nghiệp, nếu phát hiện mắc bệnh trong thời gian quy định thì được giám định để xem xét giải quyết chế độ. Ngoài điều kiện này, vẫn phải đáp ứng khoản 1 Điều 46: bệnh thuộc Danh mục và suy giảm khả năng lao động từ 5% trở lên do bệnh đó.",
    877: "Được hưởng trợ cấp một lần nếu mức suy giảm khả năng lao động từ 5% đến 30%.",
    878: "Được hưởng trợ cấp hằng tháng nếu mức suy giảm khả năng lao động từ 31% trở lên.",
    880: "Có, nhưng yêu cầu phụ thuộc nhóm công việc. Người làm công việc có yêu cầu nghiêm ngặt phải được huấn luyện và cấp thẻ an toàn trước khi bố trí. Với người lao động không thuộc các nhóm tại khoản 1, 2, 3 Điều 14, người sử dụng lao động phải tự tổ chức huấn luyện trước khi tuyển dụng hoặc bố trí làm việc và huấn luyện định kỳ. Vì vậy cần xác định nhóm của vị trí cụ thể, không áp dụng một thủ tục giống nhau cho mọi người.",
    884: "Chưa đủ dữ kiện để kết luận người lao động thuộc nhóm 4 vì đề bài mới loại trừ nhóm 2 và 3, chưa xác định họ có phải người quản lý phụ trách an toàn (nhóm 1) hoặc người làm công tác y tế (nhóm 5). Theo khoản 4 Điều 17 Nghị định 44/2016/NĐ-CP, nhóm 4 gồm người lao động không thuộc nhóm 1, 2, 3, 5; an toàn, vệ sinh viên thuộc nhóm 6 nhưng nhóm 6 không được liệt kê là trường hợp loại trừ ở khoản 4. Nếu người này đồng thời là an toàn, vệ sinh viên và không thuộc nhóm 1 hoặc 5 thì cần huấn luyện nhóm 4 cùng nội dung bổ sung của nhóm 6.",
    888: "Có, nhưng yêu cầu phụ thuộc nhóm công việc. Người làm công việc có yêu cầu nghiêm ngặt phải được huấn luyện và cấp thẻ an toàn trước khi bố trí. Với người lao động không thuộc các nhóm tại khoản 1, 2, 3 Điều 14, người sử dụng lao động phải tự tổ chức huấn luyện trước khi tuyển dụng hoặc bố trí làm việc và huấn luyện định kỳ. Vì vậy cần xác định nhóm của vị trí cụ thể, không áp dụng một thủ tục giống nhau cho mọi người.",
    892: "Chưa đủ dữ kiện để kết luận Anh Nam thuộc nhóm 4 vì đề bài mới loại trừ nhóm 2 và 3, chưa xác định Anh có phải người quản lý phụ trách an toàn (nhóm 1) hoặc người làm công tác y tế (nhóm 5). Theo khoản 4 Điều 17 Nghị định 44/2016/NĐ-CP, nhóm 4 gồm người lao động không thuộc nhóm 1, 2, 3, 5; an toàn, vệ sinh viên thuộc nhóm 6 nhưng nhóm 6 không được liệt kê là trường hợp loại trừ ở khoản 4. Nếu Anh đồng thời là an toàn, vệ sinh viên và không thuộc nhóm 1 hoặc 5 thì cần huấn luyện nhóm 4 cùng nội dung bổ sung của nhóm 6.",
    907: "Có. Người sử dụng lao động phải trang cấp miễn phí phương tiện bảo vệ cá nhân đúng chủng loại, đúng đối tượng, đủ số lượng và bảo đảm chất lượng; không được phát tiền thay, buộc người lao động tự mua hoặc thu tiền của họ để mua phương tiện. Đồng thời phải hướng dẫn, giám sát việc sử dụng.",
    912: "Có. Người sử dụng lao động phải trang cấp miễn phí phương tiện bảo vệ cá nhân đúng chủng loại, đúng đối tượng, đủ số lượng và bảo đảm chất lượng; không được phát tiền thay, buộc người lao động tự mua hoặc thu tiền của họ để mua phương tiện. Đồng thời phải hướng dẫn, giám sát việc sử dụng.",
    920: "Có. Người nước ngoài kết hôn với người Việt Nam và sinh sống trên lãnh thổ Việt Nam thuộc trường hợp không phải cấp giấy phép lao động theo khoản 8 Điều 154 Bộ luật Lao động. Theo khoản 4 Điều 9 Nghị định 219/2025/NĐ-CP, người sử dụng lao động không phải xin giấy xác nhận nhưng vẫn phải thông báo với cơ quan có thẩm quyền ít nhất 03 ngày làm việc trước ngày dự kiến bắt đầu làm việc.",
    956: "Nếu thời hạn làm việc thỏa thuận trong hợp đồng đưa người lao động Việt Nam đi làm việc ở nước ngoài từ đủ 36 tháng trở lên, mức trần tiền dịch vụ thu từ người lao động là không quá 03 tháng tiền lương theo hợp đồng lao động. Nếu bên nước ngoài tiếp nhận lao động đã trả một phần tiền dịch vụ, doanh nghiệp chỉ được thu phần còn thiếu và vẫn phải nằm trong giới hạn này.",
    957: "Có. Doanh nghiệp dịch vụ phải ký quỹ tại ngân hàng; tiền ký quỹ chỉ được sử dụng theo yêu cầu của cơ quan có thẩm quyền khi doanh nghiệp không thực hiện hoặc thực hiện không đầy đủ nghĩa vụ. Nếu tiền ký quỹ đã được sử dụng, doanh nghiệp phải hoàn trả số đã dùng và khôi phục đủ mức ký quỹ trong 30 ngày kể từ ngày sử dụng.",
    966: "Nếu thời hạn làm việc thỏa thuận trong hợp đồng đưa người lao động Việt Nam đi làm việc ở nước ngoài từ đủ 36 tháng trở lên, mức trần tiền dịch vụ thu từ người lao động là không quá 03 tháng tiền lương theo hợp đồng lao động. Nếu bên nước ngoài tiếp nhận lao động đã trả một phần tiền dịch vụ, doanh nghiệp chỉ được thu phần còn thiếu và vẫn phải nằm trong giới hạn này.",
    970: "Không thể kết luận chỉ từ tên “hợp đồng cộng tác viên”. Nếu thỏa thuận thực tế có việc làm trả công, tiền lương và sự quản lý, điều hành, giám sát của doanh nghiệp thì có thể được coi là hợp đồng lao động theo khoản 1 Điều 13 Bộ luật Lao động. BHXH bắt buộc áp dụng nếu đáp ứng đối tượng tại điểm a khoản 1 Điều 2 Luật BHXH (hợp đồng không xác định thời hạn hoặc từ đủ 01 tháng); với người làm không trọn thời gian, còn phải đối chiếu điểm l khoản 1 Điều 2 về mức lương tháng tối thiểu làm căn cứ đóng. Cần biết thời hạn và việc làm toàn thời gian hay bán thời gian để kết luận trường hợp cụ thể.",
    971: "Có, nhưng không phải mọi đối tượng đều áp dụng quy định này. Theo khoản 1 Điều 3 Nghị định 158/2025/NĐ-CP, người thuộc điểm a, b, c, i, k, l khoản 1 và khoản 2 Điều 2 Luật BHXH được cử đi học, thực tập hoặc công tác trong/ngoài nước mà vẫn hưởng tiền lương ở trong nước thì tiếp tục thuộc diện tham gia BHXH bắt buộc.",
    988: "Có. Lao động nam có thời gian đóng cao hơn 35 năm khi nghỉ hưu được hưởng trợ cấp một lần cho phần vượt. Mỗi năm đóng cao hơn đến tuổi nghỉ hưu được tính bằng 0,5 lần mức bình quân tiền lương làm căn cứ đóng BHXH. Nếu người lao động đã đủ điều kiện hưởng lương hưu nhưng tiếp tục đóng BHXH sau tuổi nghỉ hưu, phần thời gian đóng thêm đó được tính bằng 02 lần mức bình quân cho mỗi năm. Vì vậy, để tính chính xác cho trường hợp 38 năm cần biết có năm đóng nào sau khi đã đủ tuổi và điều kiện hưởng lương hưu hay không.",
    1001: "Có, hợp đồng lao động xác định thời hạn 02 tháng thuộc diện tham gia BHTN vì ngưỡng thông thường là từ đủ 01 tháng, không phải 03 tháng. Tuy nhiên, nếu làm không trọn thời gian thì tiền lương trong tháng phải bằng hoặc cao hơn mức thấp nhất làm căn cứ đóng BHXH bắt buộc. Ngoài ra, người đang hưởng lương hưu, trợ cấp BHXH hoặc trợ cấp hằng tháng theo quy định của Chính phủ, người đã đủ điều kiện hưởng lương hưu, người đang làm theo hợp đồng thử việc và người giúp việc gia đình thuộc các trường hợp không tham gia BHTN theo khoản 2 Điều 31. Vì vậy cần kiểm tra các điều kiện và ngoại lệ này trước khi kết luận cho một người cụ thể.",
    1002: "Không. Với tình huống đang thử việc theo hợp đồng thử việc riêng, người lao động không thuộc đối tượng tham gia BHTN theo khoản 2 Điều 31 Luật Việc làm. Lưu ý Bộ luật Lao động cho phép thỏa thuận thử việc bằng hợp đồng riêng hoặc ghi nội dung thử việc trong hợp đồng lao động; nếu thử việc được ghi trong hợp đồng lao động thì phải xét loại và thời hạn hợp đồng cùng các điều kiện tại khoản 1 Điều 31, không nên kết luận máy móc rằng mọi trường hợp đang thử việc đều không tham gia BHTN.",
    1003: "Mức đóng thông thường là người lao động 1% tiền lương tháng, người sử dụng lao động 1% quỹ tiền lương tháng của người lao động đang tham gia BHTN; Nhà nước hỗ trợ Quỹ BHTN tối đa 1% quỹ tiền lương tháng đó. Riêng người sử dụng lao động tuyển mới và sử dụng lao động là người khuyết tật có thể được giảm phần đóng của mình từ 1% xuống 0% cho người lao động đó, tối đa trong 12 tháng đầu kể từ khi tuyển mới.",
    1005: "Hồ sơ gồm: (1) đề nghị hưởng trợ cấp thất nghiệp theo Mẫu số 10; (2) một giấy tờ xác nhận việc chấm dứt hợp đồng/làm việc, nộp theo một trong các hình thức bản chính, bản sao có chứng thực, bản chính kèm bản sao để đối chiếu hoặc bản điện tử; và (3) sổ bảo hiểm xã hội. Giấy tờ chấm dứt có thể là hợp đồng đã hết hạn/hoàn thành, quyết định thôi việc, sa thải, kỷ luật buộc thôi việc, thông báo/thỏa thuận chấm dứt hoặc xác nhận của người sử dụng lao động theo nội dung luật định. Đây là thành phần hồ sơ; người lao động còn phải đáp ứng các điều kiện hưởng khác.",
    1006: "Mức trợ cấp hằng tháng bằng 60% mức bình quân tiền lương tháng đóng BHTN của 06 tháng liền kề có đóng BHTN gần nhất trước khi thất nghiệp. Nếu các tháng cuối bị gián đoạn đóng, lấy 06 tháng có đóng trước khi chấm dứt hợp đồng/làm việc. Mức hưởng còn chịu trần tối đa 05 lần mức lương tối thiểu tháng theo vùng được áp dụng tại tháng cuối cùng đóng BHTN.",
    1007: "Có. Trong thời gian hưởng trợ cấp thất nghiệp, người lao động phải thông báo hằng tháng về việc tìm kiếm việc làm cho tổ chức dịch vụ việc làm công nơi đang hưởng trợ cấp. Nếu không thông báo, trợ cấp bị tạm dừng; trong thời gian tạm dừng không được nhận tiền và thời gian đó không được bảo lưu. Nếu vẫn còn thời gian hưởng, người lao động được tiếp tục hưởng khi thực hiện lại việc thông báo theo quy định.",
    886: "An toàn, vệ sinh viên thuộc nhóm 6. Ngoài nội dung huấn luyện an toàn, vệ sinh lao động theo quy định, họ được huấn luyện bổ sung kỹ năng và phương pháp hoạt động; thời lượng bổ sung tối thiểu là 04 giờ. Căn cứ là khoản 6 Điều 17, khoản 6 Điều 18 và khoản 5 Điều 19 Nghị định 44/2016/NĐ-CP.",
    894: "An toàn, vệ sinh viên thuộc nhóm 6. Ngoài nội dung huấn luyện an toàn, vệ sinh lao động theo quy định, họ được huấn luyện bổ sung kỹ năng và phương pháp hoạt động; thời lượng bổ sung tối thiểu là 04 giờ. Căn cứ là khoản 6 Điều 17, khoản 6 Điều 18 và khoản 5 Điều 19 Nghị định 44/2016/NĐ-CP.",
    899: "Cơ sở sản xuất, kinh doanh phải thanh toán chi phí kiểm định kỹ thuật an toàn lao động; khoản chi này được hạch toán vào chi phí sản xuất, kinh doanh theo khoản 5 Điều 45 Nghị định 44/2016/NĐ-CP.",
    904: "Cơ sở sản xuất, kinh doanh phải thanh toán chi phí kiểm định kỹ thuật an toàn lao động; khoản chi này được hạch toán vào chi phí sản xuất, kinh doanh theo khoản 5 Điều 45 Nghị định 44/2016/NĐ-CP.",
    787: "Người làm công việc có yêu cầu nghiêm ngặt về an toàn, vệ sinh lao động thuộc nhóm 3. Người sử dụng lao động phải tổ chức huấn luyện, kiểm tra đạt yêu cầu và cấp thẻ an toàn trước khi bố trí làm công việc này.",
    789: "Người làm công việc có yêu cầu nghiêm ngặt về an toàn, vệ sinh lao động thuộc nhóm 3. Người sử dụng lao động phải tổ chức huấn luyện, kiểm tra đạt yêu cầu và cấp thẻ an toàn trước khi bố trí làm công việc này.",
    883: "Người làm công việc có yêu cầu nghiêm ngặt về an toàn, vệ sinh lao động thuộc nhóm 3. Người sử dụng lao động phải tổ chức huấn luyện, kiểm tra đạt yêu cầu và cấp thẻ an toàn trước khi bố trí làm công việc này.",
    891: "Người làm công việc có yêu cầu nghiêm ngặt về an toàn, vệ sinh lao động thuộc nhóm 3. Người sử dụng lao động phải tổ chức huấn luyện, kiểm tra đạt yêu cầu và cấp thẻ an toàn trước khi bố trí làm công việc này.",
    788: "Không. Không thể thay việc huấn luyện thực chất bằng ký xác nhận. Người sử dụng lao động phải huấn luyện đúng đối tượng, nội dung và thời lượng, tổ chức kiểm tra/đánh giá theo quy định. Nếu tự tổ chức nhưng cung cấp kết quả huấn luyện khống hoặc thuê đơn vị cấp kết quả dù không huấn luyện, người sử dụng lao động có thể bị xử phạt; đơn vị huấn luyện cũng có thể bị xử phạt nếu cung cấp kết quả không đúng thực tế.",
    887: "Không. Không thể thay việc huấn luyện thực chất bằng ký xác nhận. Người sử dụng lao động phải huấn luyện đúng đối tượng, nội dung và thời lượng, tổ chức kiểm tra/đánh giá theo quy định. Nếu tự tổ chức nhưng cung cấp kết quả huấn luyện khống hoặc thuê đơn vị cấp kết quả dù không huấn luyện, người sử dụng lao động có thể bị xử phạt; đơn vị huấn luyện cũng có thể bị xử phạt nếu cung cấp kết quả không đúng thực tế.",
    807: "Có. Người lao động Việt Nam đi làm việc ở nước ngoài theo hợp đồng có quyền được tư vấn, hỗ trợ để thực hiện quyền, nghĩa vụ và hưởng lợi ích trong hợp đồng lao động, hợp đồng đào tạo nghề. Căn cứ điểm b khoản 1 Điều 6 Luật 69/2020/QH14.",
    953: "Có. Người lao động Việt Nam đi làm việc ở nước ngoài theo hợp đồng có quyền được tư vấn, hỗ trợ để thực hiện quyền, nghĩa vụ và hưởng lợi ích trong hợp đồng lao động, hợp đồng đào tạo nghề. Căn cứ điểm b khoản 1 Điều 6 Luật 69/2020/QH14.",
    963: "Có. Người lao động Việt Nam đi làm việc ở nước ngoài theo hợp đồng có quyền được tư vấn, hỗ trợ để thực hiện quyền, nghĩa vụ và hưởng lợi ích trong hợp đồng lao động, hợp đồng đào tạo nghề. Căn cứ điểm b khoản 1 Điều 6 Luật 69/2020/QH14.",
    431: "Với người thuộc điểm a, b, c, d, i khoản 1 và khoản 2 Điều 2 Luật BHXH, nếu không hưởng tiền lương từ 14 ngày làm việc trở lên trong tháng thì không phải đóng BHXH tháng đó, trừ khi hai bên thỏa thuận tiếp tục đóng theo căn cứ đóng của tháng gần nhất. Với người thuộc điểm đ, e, k khoản 1, nếu không làm việc từ 14 ngày làm việc trở lên thì thực hiện theo quy định của Chính phủ. Riêng tháng đầu làm việc hoặc tháng đầu trở lại làm việc, người lao động nghỉ hưởng chế độ ốm đau từ 14 ngày làm việc trở lên vẫn phải đóng BHXH tháng đó.",
    715: "Tranh chấp lao động tập thể về quyền là tranh chấp giữa một hay nhiều tổ chức đại diện người lao động với người sử dụng lao động hoặc một hay nhiều tổ chức của người sử dụng lao động, phát sinh từ việc giải thích hoặc thực hiện khác nhau quy định pháp luật lao động, thỏa ước, nội quy, quy chế hay thỏa thuận hợp pháp; hoặc từ hành vi phân biệt đối xử, can thiệp/thao túng tổ chức đại diện người lao động hay vi phạm nghĩa vụ thương lượng thiện chí.",
    727: "Ít nhất 05 ngày làm việc trước ngày bắt đầu đình công, tổ chức đại diện người lao động tổ chức và lãnh đạo đình công phải gửi văn bản quyết định đình công cho người sử dụng lao động, Ủy ban nhân dân cấp xã và cơ quan chuyên môn thực hiện nhiệm vụ về lĩnh vực nội vụ thuộc Ủy ban nhân dân cấp tỉnh. Điều 68 Nghị định 129/2025/NĐ-CP quy định cách thực hiện khoản 3 Điều 202 Bộ luật Lao động.",
    757: "Ít nhất 05 ngày làm việc trước ngày bắt đầu đình công. Theo Điều 68 Nghị định 129/2025/NĐ-CP, văn bản quyết định đình công phải gửi cho người sử dụng lao động, Ủy ban nhân dân cấp xã và cơ quan chuyên môn thực hiện nhiệm vụ về lĩnh vực nội vụ thuộc Ủy ban nhân dân cấp tỉnh.",
    744: "Không được đình công tại nơi sử dụng lao động mà cuộc đình công có thể đe dọa quốc phòng, an ninh, trật tự công cộng hoặc sức khỏe con người. Phụ lục VI Nghị định 145/2020/NĐ-CP liệt kê cụ thể các đơn vị thuộc 06 nhóm: điện lực; dầu khí; an toàn hàng không/hàng hải; hạ tầng thông tin-truyền thông; cấp nước, thoát nước và vệ sinh môi trường trực tiếp phục vụ thành phố trực thuộc Trung ương; doanh nghiệp trực tiếp phục vụ quốc phòng, an ninh. Cần đối chiếu đúng tên đơn vị trong phụ lục, không suy rộng rằng mọi doanh nghiệp cùng ngành đều bị cấm đình công.",
    783: "Người lao động phải mắc bệnh nghề nghiệp thuộc Danh mục bệnh nghề nghiệp do Bộ trưởng Bộ Y tế ban hành và bị suy giảm khả năng lao động từ 5% trở lên do bệnh đó. Cả bệnh thuộc danh mục và mức suy giảm là điều kiện theo khoản 1 Điều 46.",
    785: "Người lao động phải mắc bệnh nghề nghiệp thuộc Danh mục bệnh nghề nghiệp do Bộ trưởng Bộ Y tế ban hành và bị suy giảm khả năng lao động từ 5% trở lên do bệnh đó. Cả bệnh thuộc danh mục và mức suy giảm là điều kiện theo khoản 1 Điều 46.",
    759: "Không. Dùng bạo lực hoặc phá hoại máy móc, thiết bị, tài sản; xâm phạm trật tự, an toàn công cộng là các hành vi bị nghiêm cấm trước, trong và sau đình công.",
    414: "Cần tách theo thời điểm. Từ 01/07/2025 đến hết 31/12/2025, chủ hộ của hộ có đăng ký kinh doanh nộp thuế theo phương pháp kê khai thuộc diện BHXH bắt buộc. Từ 01/01/2026, không thể chỉ xét phương pháp kê khai: chủ hộ của hộ đã đăng ký kinh doanh có doanh thu năm trên 01 tỷ đồng và thuộc diện phải nộp thuế giá trị gia tăng, thuế thu nhập cá nhân thuộc diện BHXH bắt buộc. Chủ hộ có doanh thu từ 01 tỷ đồng trở xuống hiện chưa thuộc diện bắt buộc theo tiêu chí này; các chủ hộ đăng ký kinh doanh còn lại theo lộ trình từ 01/07/2029.",
    415: "Không phải tất cả chủ hộ đều phải tham gia ngay từ năm 2025. Từ 01/07/2025 đến hết 31/12/2025, chủ hộ của hộ có đăng ký kinh doanh không thuộc nhóm nộp thuế theo phương pháp kê khai thuộc diện BHXH bắt buộc theo lộ trình từ 01/07/2029. Nhưng từ 01/01/2026, tiêu chí đã thay đổi: chủ hộ của hộ đăng ký kinh doanh có doanh thu năm trên 01 tỷ đồng và thuộc diện phải nộp thuế giá trị gia tăng, thuế thu nhập cá nhân thuộc diện BHXH bắt buộc; chủ hộ có doanh thu từ 01 tỷ đồng trở xuống hiện chưa bắt buộc theo tiêu chí này. Vì vậy cần xét cả thời điểm và doanh thu, không chỉ dựa vào cách kê khai thuế.",
    417: "Không phải đóng hai lần đồng thời cho cùng thời gian. Luật BHXH giao Chính phủ quy định trường hợp chủ hộ kinh doanh đồng thời thuộc diện BHXH bắt buộc khác; điểm a khoản 3 Điều 3 Nghị định 158/2025/NĐ-CP yêu cầu áp dụng nhóm đối tượng tương ứng theo thứ tự ưu tiên. Nếu người đó đồng thời chỉ thuộc hai nhóm nêu trong câu hỏi — chủ hộ kinh doanh và người lao động theo HĐLĐ thuộc diện bắt buộc — thì đóng theo tư cách người lao động theo HĐLĐ, không đóng thêm lần nữa theo tư cách chủ hộ. Việc chủ hộ có thuộc diện bắt buộc nếu xét riêng tư cách này cần xác định theo mốc thời gian: từ 01/07/2025 đến hết 31/12/2025 là nhóm hộ đăng ký kinh doanh nộp thuế theo phương pháp kê khai; từ 01/01/2026 là chủ hộ của hộ đăng ký kinh doanh có doanh thu năm trên 01 tỷ đồng và thuộc diện chịu thuế GTGT, TNCN; các chủ hộ đăng ký kinh doanh còn lại theo lộ trình từ 01/07/2029.",
}

